/* Tech Robot · unitat 4 «En Bit veu el món» (sensors i condicions) */
Object.assign(TBADGE, {
  u4sens: { id: 'u4sens', ico: '👀', n: 'Ulls de robot|Ojos de robot', d: "Has fet servir el sensor d'en Bit per decidir quan gira.|Has usado el sensor de Bit para decidir cuándo gira." },
  u4dec: { id: 'u4dec', ico: '🔀', n: 'Decideix!|¡Decide!', d: 'Has programat decisions amb «Si… si no…».|Has programado decisiones con «Si… si no…».' },
  u4lab: { id: 'u4lab', ico: '🏆', n: 'Surts del laberint|Sales del laberinto', d: "Has fet sortir en Bit de laberints diferents amb una sola estratègia.|Has hecho salir a Bit de laberintos diferentes con una sola estrategia." }
});
ROBOT_UNITS[4] = { t: 'En Bit veu el món|Bit ve el mundo', d: 'Sensors i condicions|Sensores y condiciones', color: '#E8A317', s: [
  { id: 'r4-1', t: 'Si hi ha una paret…|Si hay una pared…', min: 35, badge: 'u4sens',
    learn: ["Un sensor és com un ull del robot: li diu com és el món que té al voltant.|Un sensor es como un ojo del robot: le dice cómo es el mundo que tiene alrededor.",
      "El bloc «Si…» fa els blocs de dins només quan la condició és certa.|El bloque «Si…» hace los bloques de dentro solo cuando la condición es cierta.",
      "Amb un «Si» dins d'un «Repeteix», el mateix programa funciona en illes diferents.|Con un «Si» dentro de un «Repite», el mismo programa funciona en islas diferentes."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'Recordes els bucles? Quin programa fa el mateix que <b>Endavant, Endavant, Endavant, Endavant</b>?|¿Recuerdas los bucles? ¿Qué programa hace lo mismo que <b>Adelante, Adelante, Adelante, Adelante</b>?',
        opts: ['«Repeteix 4 vegades: Endavant»|«Repite 4 veces: Adelante»', '«Repeteix 2 vegades: Endavant»|«Repite 2 veces: Adelante»', '«Repeteix 4 vegades: Gira a la dreta»|«Repite 4 veces: Gira a la derecha»'], a: 0,
        ex: 'El bucle fa 4 vegades el bloc de dins: 4 passos endavant.|El bucle hace 4 veces el bloque de dentro: 4 pasos adelante.' },
      { k: 'quiz', ph: 'recorda', q: 'A la unitat passada vas fer servir el bloc <b>Quan premo A</b>. Quan fa en Bit els blocs de dins?|En la unidad pasada usaste el bloque <b>Al pulsar A</b>. ¿Cuándo hace Bit los bloques de dentro?',
        opts: ['Només quan algú prem el botó A|Solo cuando alguien pulsa el botón A', 'Sempre, al principi del programa|Siempre, al principio del programa', 'Mai|Nunca'], a: 0,
        ex: 'Exacte: <b>només quan</b> passa una cosa. Avui aprendràs un bloc que també funciona així.|Exacto: <b>solo cuando</b> pasa algo. Hoy aprenderás un bloque que también funciona así.' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: 'La boira del matí|La niebla de la mañana',
        t: "Cada matí, una boira espessa cobreix l'illa. I aquesta nit el vent ha bufat tan fort que <b>ha mogut les roques</b> de lloc! Els programes d'ahir ja no serveixen: en Bit xocaria.|Cada mañana, una niebla espesa cubre la isla. ¡Y esta noche el viento ha soplado tan fuerte que <b>ha movido las rocas</b> de sitio! Los programas de ayer ya no sirven: Bit chocaría." },
      { k: 'story', ph: 'missio', who: 'bit', scene: 'lab', mood: 'happy',
        t: "BIP! En Numi m'ha posat una peça nova al davant: un <b>sensor</b>. Ara puc saber si tinc un obstacle just davant meu… i decidir què faig!|¡BIP! Numi me ha puesto una pieza nueva delante: un <b>sensor</b>. ¡Ahora puedo saber si tengo un obstáculo justo delante… y decidir qué hago!" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Sensor|Sensor', t: 'Què és un sensor?|¿Qué es un sensor?', anim: 'u4sensor',
          x: "Un <span class='hl'>sensor</span> és una peça que nota alguna cosa del món i ho explica a la màquina. Els ulls, les orelles i la pell són els nostres sensors. Les portes automàtiques s'obren perquè un sensor nota que arribes, i el sensor d'aparcament d'un cotxe xiula quan s'acosta a una paret.|Un <span class='hl'>sensor</span> es una pieza que nota algo del mundo y se lo explica a la máquina. Los ojos, los oídos y la piel son nuestros sensores. Las puertas automáticas se abren porque un sensor nota que llegas, y el sensor de aparcamiento de un coche pita cuando se acerca a una pared." },
        { k: "El sensor d'en Bit|El sensor de Bit", t: 'Mira la casella del davant|Mira la casilla de delante', anim: 'u4beam',
          x: "El sensor d'en Bit mira <b>només la casella que té just davant</b>. Si hi ha una roca, un arbre, aigua o la vora de l'illa, diu: <b>hi ha un obstacle</b>. Si s'hi pot passar, diu: <b>el camí és lliure</b>.|El sensor de Bit mira <b>solo la casilla que tiene justo delante</b>. Si hay una roca, un árbol, agua o el borde de la isla, dice: <b>hay un obstáculo</b>. Si se puede pasar, dice: <b>el camino está libre</b>." },
        { k: 'Condició|Condición', t: 'El bloc «Si…»|El bloque «Si…»', anim: 'u4if',
          x: "El bloc <span class='hl'>Si</span> fa una pregunta, que es diu <span class='hl'>condició</span>. Si la resposta és <b>sí</b>, en Bit fa els blocs de dins. Si és <b>no</b>, se'ls salta i continua. És com quan penses: «Si fa fred, em poso la jaqueta.»|El bloque <span class='hl'>Si</span> hace una pregunta, que se llama <span class='hl'>condición</span>. Si la respuesta es <b>sí</b>, Bit hace los bloques de dentro. Si es <b>no</b>, se los salta y sigue. Es como cuando piensas: «Si hace frío, me pongo la chaqueta.»" },
        { k: 'Camí lliure|Camino libre', t: 'Avança només si pots|Avanza solo si puedes', demo: { w: { map: ['......', '>###F.', '......'] }, prog: TQ('6{ if:free{ f } }') },
          x: "Aquí en Bit repeteix 6 vegades: <b>si el camí és lliure, endavant</b>. A la bandera té un arbre davant: el sensor diu que no, i en Bit ja no avança. No xoca mai!|Aquí Bit repite 6 veces: <b>si el camino está libre, adelante</b>. En la bandera tiene un árbol delante: el sensor dice que no, y Bit ya no avanza. ¡No choca nunca!" },
        { k: 'Compte!|¡Cuidado!', t: 'El «Si», dins del «Repeteix»|El «Si», dentro del «Repite»', demo: { w: { map: ['>###', '...#', '...F'] }, prog: TQ('5{ if:wall{ r } f }') },
          x: "Amb el «Si» <b>dins</b> del «Repeteix», en Bit mira el sensor <b>abans de cada pas</b>. Així, quan arriba a la vora de l'illa, el sensor diu «obstacle!», en Bit gira a la dreta i continua.|Con el «Si» <b>dentro</b> del «Repite», Bit mira el sensor <b>antes de cada paso</b>. Así, cuando llega al borde de la isla, el sensor dice «¡obstáculo!», Bit gira a la derecha y sigue.",
          bad: "Posar el «Si» fora del bucle: en Bit només mira una vegada, al principi.|Poner el «Si» fuera del bucle: Bit solo mira una vez, al principio.", good: "Posar el «Si» dins del bucle: en Bit mira a cada volta.|Poner el «Si» dentro del bucle: Bit mira en cada vuelta." }
      ] },
      { k: 'quiz', ph: 'mans', q: 'Quin d\'aquests aparells fa servir un <b>sensor</b> per saber que arriba algú?|¿Cuál de estos aparatos usa un <b>sensor</b> para saber que llega alguien?',
        opts: ['La porta automàtica del supermercat|La puerta automática del supermercado', 'Una cadira|Una silla', 'Un llapis|Un lápiz'], a: 0,
        ex: "El sensor de la porta nota que t'acostes i la porta s'obre sola. La cadira i el llapis no noten res.|El sensor de la puerta nota que te acercas y la puerta se abre sola. La silla y el lápiz no notan nada." },
      { k: 'unplug', ph: 'mans', ico: '👀', title: 'El robot i el seu sensor|El robot y su sensor',
        t: "Necessites algú de casa. Una persona fa de <b>robot</b> i l'altra, de <b>sensor</b>.|Necesitas a alguien de casa. Una persona hace de <b>robot</b> y la otra, de <b>sensor</b>.",
        steps: ['Poseu uns quants coixins a terra: són els obstacles.|Poned unos cuantos cojines en el suelo: son los obstáculos.',
          "El robot segueix aquest programa: <b>Repeteix 10 vegades: si hi ha un obstacle davant, gira a la dreta; després, fes un pas</b>.|El robot sigue este programa: <b>Repite 10 veces: si hay un obstáculo delante, gira a la derecha; después, da un paso</b>.",
          "Abans de cada pas, el sensor mira el lloc del davant i diu «Obstacle!» o «Lliure!».|Antes de cada paso, el sensor mira el sitio de delante y dice «¡Obstáculo!» o «¡Libre!».",
          'Canvieu els coixins de lloc i torneu-ho a provar amb el mateix programa. Després, canvieu els papers.|Cambiad los cojines de sitio y volved a probar con el mismo programa. Después, cambiad los papeles.'],
        tip: "Camineu a poc a poc i amb passos curts: el robot s'ha de poder aturar a temps.|Caminad despacio y con pasos cortos: el robot se tiene que poder parar a tiempo." },
      { k: 'quiz', ph: 'prova', w: { map: ['....', '.>R.', '....'] }, keep: true, q: 'En Bit mira cap a la dreta. Què dirà el seu sensor?|Bit mira hacia la derecha. ¿Qué dirá su sensor?',
        opts: ['Hi ha un obstacle davant|Hay un obstáculo delante', 'El camí és lliure|El camino está libre'], a: 0,
        ex: 'Just a la casella del davant hi ha una roca. El sensor només mira aquesta casella.|Justo en la casilla de delante hay una roca. El sensor solo mira esa casilla.' },
      { k: 'predict', ph: 'prova', q: 'En Bit fa: <b>Repeteix 4 vegades: si hi ha un obstacle davant, gira a la dreta; Endavant</b>. On acabarà?|Bit hace: <b>Repite 4 veces: si hay un obstáculo delante, gira a la derecha; Adelante</b>. ¿Dónde terminará?',
        w: { map: ['>##RA', '..#..', 'C.B..'] }, prog: TQ('4{ if:wall{ r } f }'), a: 'B',
        ex: 'Quan té la roca davant, el sensor diu «obstacle» i en Bit gira a la dreta, cap avall. Després avança fins a la B.|Cuando tiene la roca delante, el sensor dice «obstáculo» y Bit gira a la derecha, hacia abajo. Después avanza hasta la B.' },
      { k: 'spot', ph: 'investiga', q: "Aquest programa hauria de portar en Bit a la bandera, però falla. Executa'l per veure-ho i <b>toca el bloc equivocat</b>.|Este programa debería llevar a Bit a la bandera, pero falla. Ejecútalo para verlo y <b>toca el bloque equivocado</b>.",
        w: { map: ['>###', '...#', '...F'] }, prog: TPX('5{ if:wall{ l! } f }'),
        ex: "Quan troba l'obstacle, en Bit gira a l'esquerra i surt del mapa. Havia de girar a la dreta, cap a la bandera.|Cuando encuentra el obstáculo, Bit gira a la izquierda y se sale del mapa. Tenía que girar a la derecha, hacia la bandera." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Fes de robot amb sensor! Camina sense moure't del lloc. Quan algú digui <b>«Obstacle!»</b>, fes un quart de volta a la dreta. Quan digui <b>«Lliure!»</b>, continua caminant.|¡Haz de robot con sensor! Camina sin moverte del sitio. Cuando alguien diga <b>«¡Obstáculo!»</b>, da un cuarto de vuelta a la derecha. Cuando diga <b>«¡Libre!»</b>, sigue caminando." },
      { k: 'build', ph: 'repte', q: "La boira amaga on s'acaba el camí, i a cada illa té una llargada diferent. Fes un sol programa perquè en Bit <b>avanci només si el camí és lliure</b> i s'aturi a la bandera de les 3 illes.|La niebla esconde dónde termina el camino, y en cada isla tiene una longitud diferente. Haz un solo programa para que Bit <b>avance solo si el camino está libre</b> y se pare en la bandera de las 3 islas.",
        w: { map: ['......', '>####F', '......'], alts: [['......', '>##F..', '......'], ['......', '>###F.', '......']] }, pal: ['fwd', 'rep', 'if'], conds: ['free', 'wall'], sol: TQ('6{ if:free{ f } }'),
        hint: "Posa el «Si» dins del «Repeteix», i repeteix prou vegades per al camí més llarg. Per canviar la condició, toca el bloc «Si».|Pon el «Si» dentro del «Repite», y repite suficientes veces para el camino más largo. Para cambiar la condición, toca el bloque «Si».",
        after: 'Has vist? Amb el sensor, el mateix programa serveix per a camins de llargades diferents.|¿Lo has visto? Con el sensor, el mismo programa sirve para caminos de longitudes diferentes.' },
      { k: 'build', ph: 'repte', q: 'El vent ha mogut la roca! A les 3 illes en Bit fa <b>6 passos</b>, però el revolt és a llocs diferents. Fes un programa que funcioni a totes: <b>si hi ha un obstacle davant, gira a la dreta</b>.|¡El viento ha movido la roca! En las 3 islas Bit da <b>6 pasos</b>, pero la curva está en sitios diferentes. Haz un programa que funcione en todas: <b>si hay un obstáculo delante, gira a la derecha</b>.',
        w: { map: ['>####', '....#', '....F', '.....', '.....'], alts: [['>###R', '...#.', '...#.', '...F.', '.....'], ['>##R.', '..#..', '..#..', '..#..', '..F..']] }, pal: ['fwd', 'right', 'rep', 'if'], conds: ['wall', 'free'], sol: TQ('6{ if:wall{ r } f }'),
        hint: "A cada volta del bucle: primer el «Si» (per si cal girar) i després un Endavant. Quants passos fa en Bit?|En cada vuelta del bucle: primero el «Si» (por si hay que girar) y después un Adelante. ¿Cuántos pasos da Bit?" },
      { k: 'build', ph: 'repte', q: "Aquest programa fa servir el sensor, però en Bit xoca. Fes <b>Pas a pas</b> per veure quan mira el sensor i arregla el programa.|Este programa usa el sensor, pero Bit choca. Haz <b>Paso a paso</b> para ver cuándo mira el sensor y arregla el programa.",
        w: { map: ['##F..', '#....', '#....', '^....'], alts: [['R....', '###F.', '#....', '^....'], ['R....', 'R....', '####F', '^....']] }, pal: ['fwd', 'right', 'rep', 'if'], conds: ['wall', 'free'],
        prog: TQ('if:wall{ r } 5{ f }'), sol: TQ('5{ if:wall{ r } f }'),
        hint: "Quantes vegades mira el sensor? Ha de mirar abans de cada pas: el «Si» ha d'anar dins del «Repeteix».|¿Cuántas veces mira el sensor? Tiene que mirar antes de cada paso: el «Si» tiene que ir dentro del «Repite»." },
      { k: 'build', ph: 'repte', q: 'Ara el camí fa <b>dos revolts</b>, i a cada illa són a llocs diferents. En Bit sempre fa 7 passos. Ho pots fer amb <b>només 4 blocs</b>?|Ahora el camino hace <b>dos curvas</b>, y en cada isla están en sitios diferentes. Bit siempre da 7 pasos. ¿Puedes hacerlo con <b>solo 4 bloques</b>?',
        w: { map: ['>####', '....#', '...F#', '.....'], alts: [['>###R', 'F###.', '...R.', '.....'], ['>##R.', '..#..', '..#..', 'F##..']] }, pal: ['fwd', 'left', 'right', 'rep', 'if'], conds: ['wall', 'free'], max: 4, sol: TQ('7{ if:wall{ r } f }'),
        hint: "És el mateix truc d'abans: el sensor decideix quan cal girar. Només has de pensar quantes vegades repeteixes.|Es el mismo truco de antes: el sensor decide cuándo hay que girar. Solo tienes que pensar cuántas veces repites." },
      { k: 'create', ph: 'crea', name: "La ronda de l'estany|La ronda del estanque",
        q: "<b>La ronda de la boira!</b> En Bit ha de fer la volta a l'estany, recollir les estrelles i acabar a la bandera. Les dues illes són diferents, però en totes dues fa <b>11 passos</b>. Fes un programa que funcioni a les dues.|<b>¡La ronda de la niebla!</b> Bit tiene que dar la vuelta al estanque, recoger las estrellas y terminar en la bandera. Las dos islas son diferentes, pero en las dos da <b>11 pasos</b>. Haz un programa que funcione en las dos.",
        crit: ['Funciona a les 2 illes|Funciona en las 2 islas', 'Recull totes les estrelles|Recoge todas las estrellas', "Fa servir un «Si» dins d'un «Repeteix»|Usa un «Si» dentro de un «Repite»"],
        check: p => p.some(b => b.k === 'rep' && bitCountK(b.b, ['if']) > 0) ? null : "Funciona, però el «Si» ha d'anar dins d'un «Repeteix». Prova-ho!|Funciona, pero el «Si» tiene que ir dentro de un «Repite». ¡Pruébalo!",
        w: { map: ['>####', 'F~~~#', '#*##*', '.....'], alts: [['>###.', 'F~~#.', '#~~*.', '#*##.']] }, pal: ['fwd', 'left', 'right', 'rep', 'if'], conds: ['wall', 'free'], sol: TQ('11{ if:wall{ r } f }') },
      { k: 'quiz', ph: 'tanca', q: 'Quan fa en Bit els blocs que hi ha dins d\'un «Si»?|¿Cuándo hace Bit los bloques que hay dentro de un «Si»?', opts: ['Només quan la condició és certa|Solo cuando la condición es cierta', 'Sempre|Siempre', 'Mai|Nunca'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Per què posem el «Si» dins del «Repeteix»?|¿Por qué ponemos el «Si» dentro del «Repite»?', opts: ['Perquè el sensor miri abans de cada pas|Para que el sensor mire antes de cada paso', 'Perquè el programa sigui més llarg|Para que el programa sea más largo', 'Perquè en Bit vagi més de pressa|Para que Bit vaya más deprisa'], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },
  { id: 'r4-2', t: 'Els colors del terra|Los colores del suelo', min: 35,
    learn: ["El sensor de color mira la casella on és en Bit i diu de quin color és.|El sensor de color mira la casilla donde está Bit y dice de qué color es.",
      "Una regla diu què cal fer en un cas: «si el terra és vermell, gira a la dreta».|Una regla dice qué hay que hacer en un caso: «si el suelo es rojo, gira a la derecha».",
      'Cada color necessita el seu propi «Si».|Cada color necesita su propio «Si».'],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'En Bit fa: <b>Repeteix 5 vegades: si hi ha un obstacle davant, gira a la dreta; Endavant</b>. Què fa quan <b>no</b> té cap obstacle davant?|Bit hace: <b>Repite 5 veces: si hay un obstáculo delante, gira a la derecha; Adelante</b>. ¿Qué hace cuando <b>no</b> tiene ningún obstáculo delante?',
        opts: ['Només avança|Solo avanza', 'Gira i avança|Gira y avanza', "S'atura|Se para"], a: 0,
        ex: "Si la condició no es compleix, en Bit se salta el gir i fa només l'Endavant.|Si la condición no se cumple, Bit se salta el giro y hace solo el Adelante." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'poble', title: 'El jardí de les rajoles|El jardín de las baldosas',
        t: "Al poble preparen la festa major i han fet un jardí amb <b>rajoles de colors</b> per guiar els carretons de les flors. Cada color vol dir una cosa. Però en Bit… com sabrà de quin color és el terra?|En el pueblo preparan la fiesta mayor y han hecho un jardín con <b>baldosas de colores</b> para guiar las carretillas de las flores. Cada color quiere decir una cosa. Pero Bit… ¿cómo sabrá de qué color es el suelo?" },
      { k: 'story', ph: 'missio', who: 'bit', scene: 'lab', mood: 'happy',
        t: 'BIP! Tinc un segon sensor, a sota del cos: un <b>sensor de color</b>. Mira el terra que trepitjo i em diu de quin color és.|¡BIP! Tengo un segundo sensor, debajo del cuerpo: un <b>sensor de color</b>. Mira el suelo que piso y me dice de qué color es.' },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Sensor de color|Sensor de color', t: 'Un sensor que veu colors|Un sensor que ve colores', anim: 'u4color',
          x: "Un <span class='hl'>sensor de color</span> mira una superfície i diu de quin color és. A les fàbriques n'hi ha per separar objectes per colors. El d'en Bit mira cap avall: <b>la casella on és ell</b>, no la del davant.|Un <span class='hl'>sensor de color</span> mira una superficie y dice de qué color es. En las fábricas los hay para separar objetos por colores. El de Bit mira hacia abajo: <b>la casilla donde está él</b>, no la de delante." },
        { k: 'Regla|Regla', t: 'Si el terra és vermell, gira|Si el suelo es rojo, gira', demo: { w: { map: ['>..r.', '.....', '...F.'] }, prog: TQ('5{ if:floor:r{ r } f }') },
          x: "Una <span class='hl'>regla</span> diu què cal fer en un cas: <b>si el terra és vermell, gira a la dreta</b>. Mira: en Bit avança, i quan trepitja la rajola vermella, gira. Per això la rajola és just al lloc del revolt.|Una <span class='hl'>regla</span> dice qué hay que hacer en un caso: <b>si el suelo es rojo, gira a la derecha</b>. Mira: Bit avanza, y cuando pisa la baldosa roja, gira. Por eso la baldosa está justo en el sitio de la curva.",
          tip: 'Els semàfors també funcionen amb una regla: «si el llum és vermell, para».|Los semáforos también funcionan con una regla: «si la luz está roja, para».' },
        { k: 'Dues regles|Dos reglas', t: "Vermell a la dreta, blau a l'esquerra|Rojo a la derecha, azul a la izquierda", demo: { w: { map: ['>.r...', '......', '..u.F.', '......'] }, prog: TQ('6{ if:floor:r{ r } if:floor:u{ l } f }') },
          x: "Amb dues regles, en Bit pot baixar escales: <b>si el terra és vermell, gira a la dreta</b>; <b>si és blau, gira a l'esquerra</b>. Cada color té el seu propi «Si».|Con dos reglas, Bit puede bajar escaleras: <b>si el suelo es rojo, gira a la derecha</b>; <b>si es azul, gira a la izquierda</b>. Cada color tiene su propio «Si»." },
        { k: 'Compte!|¡Cuidado!', t: 'El terra musical|El suelo musical', demo: { w: { map: ['......', '>rurF.', '......'], melody: ['do', 'sol', 'do'] }, prog: TQ('4{ f if:floor:r{ note:do } if:floor:u{ note:sol } }') },
          x: "Les regles no només serveixen per girar. Aquí, quan en Bit trepitja vermell toca un <b>do</b>, i quan trepitja blau toca un <b>sol</b>. Fixa't que primer fa <b>Endavant</b> i després mira el terra: el sensor de color mira <b>la casella on és</b>, no la del davant.|Las reglas no solo sirven para girar. Aquí, cuando Bit pisa rojo toca un <b>do</b>, y cuando pisa azul toca un <b>sol</b>. Fíjate en que primero hace <b>Adelante</b> y después mira el suelo: el sensor de color mira <b>la casilla donde está</b>, no la de delante.",
          bad: 'Pensar que el sensor de color mira la casella del davant.|Pensar que el sensor de color mira la casilla de delante.', good: 'El sensor de color mira la casella on és en Bit.|El sensor de color mira la casilla donde está Bit.' }
      ] },
      { k: 'quiz', ph: 'mans', w: { map: ['.....', '..v..', '..u..', '.....'] }, q: "En Bit baixarà i trepitjarà la rajola blava, que vol dir <b>gira a l'esquerra</b>. Cap on anirà després, a la pantalla?|Bit bajará y pisará la baldosa azul, que quiere decir <b>gira a la izquierda</b>. ¿Hacia dónde irá después, en la pantalla?",
        opts: ['→ Cap a la dreta de la pantalla|→ Hacia la derecha de la pantalla', "← Cap a l'esquerra de la pantalla|← Hacia la izquierda de la pantalla", '↓ Continuarà avall|↓ Seguirá hacia abajo'], a: 0,
        ex: "Posa't al lloc d'en Bit: mira avall, i la seva esquerra és la teva dreta.|Ponte en el lugar de Bit: mira abajo, y su izquierda es tu derecha." },
      { k: 'unplug', ph: 'mans', ico: '🎨', title: 'El terra de colors|El suelo de colores', t: 'Amb algú de casa i uns quants papers de colors (o tovallons, o peces de roba).|Con alguien de casa y unos cuantos papeles de colores (o servilletas, o prendas de ropa).',
        steps: ["Feu un camí a terra amb revolts. Poseu un paper <b>vermell</b> a cada revolt cap a la dreta i un de <b>blau</b> a cada revolt cap a l'esquerra.|Haced un camino en el suelo con curvas. Poned un papel <b>rojo</b> en cada curva hacia la derecha y uno <b>azul</b> en cada curva hacia la izquierda.",
          "El robot camina pas a pas i només segueix les regles: si trepitja vermell, gira a la dreta; si trepitja blau, gira a l'esquerra.|El robot camina paso a paso y solo sigue las reglas: si pisa rojo, gira a la derecha; si pisa azul, gira a la izquierda.",
          'Inventeu una regla nova: per exemple, si trepitja groc, pica de mans.|Inventad una regla nueva: por ejemplo, si pisa amarillo, da una palmada.',
          "Canvieu el camí: el robot no ha de saber per on va, només les regles!|Cambiad el camino: ¡el robot no tiene que saber por dónde va, solo las reglas!"] },
      { k: 'predict', ph: 'prova', q: "Programa: <b>Repeteix 5 vegades: si el terra és vermell, gira a la dreta; si és blau, gira a l'esquerra; Endavant</b>. On acabarà en Bit?|Programa: <b>Repite 5 veces: si el suelo es rojo, gira a la derecha; si es azul, gira a la izquierda; Adelante</b>. ¿Dónde terminará Bit?",
        w: { map: ['..r.A', '>.u.B', '.....', '..C..'] }, prog: TQ('5{ if:floor:r{ r } if:floor:u{ l } f }'), a: 'A',
        ex: "A la rajola blava gira a l'esquerra (amunt); a la vermella, a la dreta. Acaba a la A.|En la baldosa azul gira a la izquierda (arriba); en la roja, a la derecha. Termina en la A." },
      { k: 'spot', ph: 'investiga', q: 'En aquest jardí, la rajola vermella vol dir <b>gira a la dreta</b>. El programa falla: <b>toca el bloc equivocat</b>.|En este jardín, la baldosa roja quiere decir <b>gira a la derecha</b>. El programa falla: <b>toca el bloque equivocado</b>.',
        w: { map: ['>..r.', '.....', '...F.'] }, prog: TPX('5{ if:floor:r{ l! } f }'),
        ex: "Dins del «Si» hi ha «Gira a l'esquerra», però la regla diu que el vermell vol dir girar a la dreta.|Dentro del «Si» está «Gira a la izquierda», pero la regla dice que el rojo quiere decir girar a la derecha." },
      { k: 'move', ph: 'pausa', secs: 30, t: '<b>El semàfor de colors!</b> Algú diu un color: <b>vermell</b>, gira a la dreta; <b>blau</b>, gira a l\'esquerra; <b>verd</b>, fes un salt; <b>groc</b>, pica de mans. Cada vegada més de pressa!|<b>¡El semáforo de colores!</b> Alguien dice un color: <b>rojo</b>, gira a la derecha; <b>azul</b>, gira a la izquierda; <b>verde</b>, da un salto; <b>amarillo</b>, da una palmada. ¡Cada vez más deprisa!' },
      { k: 'build', ph: 'repte', q: 'Al jardí, les rajoles vermelles volen dir <b>gira a la dreta</b>. A les 3 illes en Bit fa <b>5 passos</b>, però la rajola és a llocs diferents. Fes un sol programa que funcioni a totes.|En el jardín, las baldosas rojas quieren decir <b>gira a la derecha</b>. En las 3 islas Bit da <b>5 pasos</b>, pero la baldosa está en sitios diferentes. Haz un solo programa que funcione en todas.',
        w: { map: ['>.r..', '.....', '.....', '..F..'], alts: [['>..r.', '.....', '...F.', '.....'], ['>...r', '....F', '.....', '.....']] }, pal: ['fwd', 'right', 'rep', 'if'], conds: ['floor:r', 'wall'], sol: TQ('5{ if:floor:r{ r } f }'),
        hint: 'A cada pas, en Bit mira el terra: si és vermell, gira a la dreta. Després, endavant. Toca el «Si» per triar la condició.|En cada paso, Bit mira el suelo: si es rojo, gira a la derecha. Después, adelante. Toca el «Si» para elegir la condición.' },
      { k: 'build', ph: 'repte', q: "Ara hi ha dues regles: <b>vermell, gira a la dreta</b> i <b>blau, gira a l'esquerra</b>. En Bit fa 6 passos a cada illa. Ho pots fer amb <b>6 blocs</b>?|Ahora hay dos reglas: <b>rojo, gira a la derecha</b> y <b>azul, gira a la izquierda</b>. Bit da 6 pasos en cada isla. ¿Puedes hacerlo con <b>6 bloques</b>?",
        w: { map: ['>.r...', '......', '..u.F.', '......'], alts: [['>r....', '.u.r..', '......', '...F..'], ['>...r.', '....uF', '......', '......']] }, pal: ['fwd', 'left', 'right', 'rep', 'if'], conds: ['floor:r', 'floor:u', 'wall'], max: 6, sol: TQ('6{ if:floor:r{ r } if:floor:u{ l } f }'),
        hint: "Necessites dos «Si» dins del «Repeteix», un per a cada color, i després l'Endavant.|Necesitas dos «Si» dentro del «Repite», uno para cada color, y después el Adelante." },
      { k: 'build', ph: 'repte', q: '<b>El pont musical de la festa!</b> Cada rajola sona: <b>vermell = do</b> i <b>blau = sol</b>. Fes que en Bit toqui la melodia de cada pont, amb el mateix programa per als 3 ponts.|<b>¡El puente musical de la fiesta!</b> Cada baldosa suena: <b>rojo = do</b> y <b>azul = sol</b>. Haz que Bit toque la melodía de cada puente, con el mismo programa para los 3 puentes.',
        w: { map: ['......', '>ruurF', '......'], melody: ['do', 'sol', 'sol', 'do'], alts: [{ map: ['......', '>rrurF', '......'], melody: ['do', 'do', 'sol', 'do'] }, { map: ['......', '>uruuF', '......'], melody: ['sol', 'do', 'sol', 'sol'] }] },
        pal: ['fwd', 'rep', 'if', 'note'], conds: ['floor:r', 'floor:u'], notes: ['do', 'sol'], sol: TQ('5{ f if:floor:r{ note:do } if:floor:u{ note:sol } }'),
        hint: 'A cada pas: endavant i, segons el color del terra, la nota que toca. Toca el bloc «Nota» per canviar-la.|En cada paso: adelante y, según el color del suelo, la nota que toca. Toca el bloque «Nota» para cambiarla.' },
      { k: 'build', ph: 'repte', q: "Aquest programa només sap la regla del vermell, i en Bit es perd. <b>Afegeix la regla que falta</b>: el blau vol dir «gira a l'esquerra».|Este programa solo sabe la regla del rojo, y Bit se pierde. <b>Añade la regla que falta</b>: el azul quiere decir «gira a la izquierda».",
        w: { map: ['>#r...', '..#...', '..u#r.', '....#.', '....F.'], alts: [['>##r..', '...u#r', '.....#', '.....F', '......']] }, pal: ['fwd', 'left', 'right', 'rep', 'if'], conds: ['floor:r', 'floor:u', 'wall'],
        prog: TQ('8{ if:floor:r{ r } f }'), sol: TQ('8{ if:floor:r{ r } if:floor:u{ l } f }'),
        hint: "Afegeix un altre «Si» dins del «Repeteix», abans de l'Endavant, i canvia'n la condició: «el terra és blau».|Añade otro «Si» dentro del «Repite», antes del Adelante, y cámbiale la condición: «el suelo es azul»." },
      { k: 'create', ph: 'crea', name: 'Els fanals de la festa|Los farolillos de la fiesta',
        q: "<b>Encén els fanals de la festa!</b> En Bit fa 8 passos pel jardí seguint les rajoles (vermell, dreta; blau, esquerra). I cada vegada que trepitja una rajola <b>groga</b>, ha d'encendre el <b>llum groc</b>. Fes un programa per a les dues illes.|<b>¡Enciende los farolillos de la fiesta!</b> Bit da 8 pasos por el jardín siguiendo las baldosas (rojo, derecha; azul, izquierda). Y cada vez que pisa una baldosa <b>amarilla</b>, tiene que encender la <b>luz amarilla</b>. Haz un programa para las dos islas.",
        crit: ['Funciona a les 2 illes|Funciona en las 2 islas', 'Segueix les rajoles vermelles i blaves|Sigue las baldosas rojas y azules', 'Encén el llum groc a cada rajola groga|Enciende la luz amarilla en cada baldosa amarilla'],
        check: p => bitCountK(p, ['if']) >= 3 ? null : 'Funciona, però fes servir un «Si» per a cada color: vermell, blau i groc.|Funciona, pero usa un «Si» para cada color: rojo, azul y amarillo.',
        w: { map: ['>yr...', '......', '..u.r.', '......', '....F.'], lights: ['y'], alts: [{ map: ['>..r..', '...y..', '...uyr', '.....F', '......'], lights: ['y', 'y'] }] },
        pal: ['fwd', 'left', 'right', 'rep', 'if', 'light'], conds: ['floor:r', 'floor:u', 'floor:y', 'wall'], colors: ['y', 'r', 'g', 'u'], sol: TQ('8{ if:floor:r{ r } if:floor:u{ l } if:floor:y{ light:y } f }') },
      { k: 'quiz', ph: 'tanca', q: "El sensor de color d'en Bit mira…|El sensor de color de Bit mira…", opts: ['La casella on és ell|La casilla donde está él', 'La casella del davant|La casilla de delante', "Tota l'illa alhora|Toda la isla a la vez"], a: 0 },
      { k: 'quiz', ph: 'tanca', q: '«Si el terra és vermell, gira a la dreta» és…|«Si el suelo es rojo, gira a la derecha» es…', opts: ['Una regla: diu què cal fer en un cas|Una regla: dice qué hay que hacer en un caso', 'Un bucle|Un bucle', 'Un error del programa|Un error del programa'], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] },
  { id: 'r4-3', t: 'Si… i si no…|Si… y si no…', min: 35, badge: 'u4dec',
    learn: ['El bloc «Si… si no…» té dues branques i en Bit en fa només una.|El bloque «Si… si no…» tiene dos ramas y Bit hace solo una.',
      "En Bit pot mirar si hi ha camí a la seva esquerra o a la seva dreta.|Bit puede mirar si hay camino a su izquierda o a su derecha.",
      "Un diagrama de decisió dibuixa les preguntes i el que passa amb cada resposta.|Un diagrama de decisión dibuja las preguntas y lo que pasa con cada respuesta."],
    steps: [
      { k: 'quiz', ph: 'recorda', q: "Quin sensor d'en Bit mira la casella on és ell?|¿Qué sensor de Bit mira la casilla donde está él?", opts: ['El sensor de color|El sensor de color', "El sensor d'obstacles|El sensor de obstáculos", 'Cap dels dos|Ninguno de los dos'], a: 0,
        ex: "El sensor de color mira avall; el d'obstacles mira la casella del davant.|El sensor de color mira abajo; el de obstáculos mira la casilla de delante." },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: 'Les cruïlles del bosc|Los cruces del bosque',
        t: "Darrere del far hi ha un bosc ple de camins que es creuen. A cada <b>cruïlla</b>, en Bit ha de decidir: per aquí o per allà? Avui aprendrà a triar entre <b>dues coses</b>.|Detrás del faro hay un bosque lleno de caminos que se cruzan. En cada <b>cruce</b>, Bit tiene que decidir: ¿por aquí o por allá? Hoy aprenderá a elegir entre <b>dos cosas</b>." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think',
        t: "BIP… Fins ara, si la condició no es complia, jo no feia res. Però de vegades vull fer <b>una cosa o una altra</b>. Per això tinc un bloc nou: <b>Si… si no…</b>|BIP… Hasta ahora, si la condición no se cumplía, yo no hacía nada. Pero a veces quiero hacer <b>una cosa u otra</b>. Por eso tengo un bloque nuevo: <b>Si… si no…</b>" },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Decidir|Decidir', t: 'Si plou… i si no?|Si llueve… ¿y si no?', anim: 'u4else',
          x: "Cada dia prens decisions: <b>si plou</b>, agafes el paraigua; <b>si no</b>, agafes la gorra. Sempre fas <b>una de les dues coses</b>, mai totes dues. Un dibuix com aquest es diu <span class='hl'>diagrama de decisió</span>.|Cada día tomas decisiones: <b>si llueve</b>, coges el paraguas; <b>si no</b>, coges la gorra. Siempre haces <b>una de las dos cosas</b>, nunca las dos. Un dibujo como este se llama <span class='hl'>diagrama de decisión</span>." },
        { k: 'Sensors dels costats|Sensores de los lados', t: "Hi ha camí a l'esquerra? I a la dreta?|¿Hay camino a la izquierda? ¿Y a la derecha?", anim: 'u4sides',
          x: "En Bit també pot mirar <b>als seus costats</b>: «hi ha camí a l'esquerra» i «hi ha camí a la dreta». Compte: són l'esquerra i la dreta <b>d'en Bit</b>, segons cap on mira ell.|Bit también puede mirar <b>a sus lados</b>: «hay camino a la izquierda» y «hay camino a la derecha». Cuidado: son la izquierda y la derecha <b>de Bit</b>, según hacia dónde mira él." },
        { k: 'Si… si no…|Si… si no…', t: 'Dues branques|Dos ramas', demo: { w: { map: ['F##..', '..#..', '..#..', '..^..'] }, prog: TQ('3{ f } if:freeL{ l } else{ r } 2{ f }') },
          x: "El bloc <span class='hl'>Si… si no…</span> té dues <span class='hl'>branques</span>. Si la condició és certa, en Bit fa la primera; <b>si no</b>, fa la segona. Aquí pregunta si hi ha camí a l'esquerra: n'hi ha, i gira a l'esquerra.|El bloque <span class='hl'>Si… si no…</span> tiene dos <span class='hl'>ramas</span>. Si la condición es cierta, Bit hace la primera; <b>si no</b>, hace la segunda. Aquí pregunta si hay camino a la izquierda: lo hay, y gira a la izquierda.",
          bad: "En Bit fa les dues branques, l'una darrere l'altra.|Bit hace las dos ramas, una detrás de otra.", good: 'En Bit fa només una branca: la del «si» o la del «si no».|Bit hace solo una rama: la del «si» o la del «si no».' },
        { k: 'Al bucle|En el bucle', t: 'Avança o gira|Avanza o gira', demo: { w: { map: ['#####', '#...F', '#....', '^....'] }, prog: TQ('10{ if:free{ f } else{ r } }') },
          x: "Dins d'un «Repeteix», en Bit decideix a cada volta: <b>si el camí és lliure, endavant; si no, gira a la dreta</b>. A cada volta fa una sola cosa: o avança o gira.|Dentro de un «Repite», Bit decide en cada vuelta: <b>si el camino está libre, adelante; si no, gira a la derecha</b>. En cada vuelta hace una sola cosa: o avanza o gira.",
          tip: "Per saber quantes voltes calen, compta els passos i els girs.|Para saber cuántas vueltas hacen falta, cuenta los pasos y los giros." },
        { k: 'Decisió dins de decisió|Decisión dentro de decisión', t: "Una pregunta després de l'altra|Una pregunta después de la otra", demo: { w: { map: ['..##F', '..#..', '###..', '#....', '^....'] }, prog: TQ('11{ if:free{ f } else{ if:freeL{ l } else{ r } } }') },
          x: "Dins del «si no» hi pot haver un altre «Si». En Bit pregunta: el camí és lliure? Si no ho és, pregunta: hi ha camí a l'esquerra? Així sap cap a quin costat ha de girar.|Dentro del «si no» puede haber otro «Si». Bit pregunta: ¿el camino está libre? Si no lo está, pregunta: ¿hay camino a la izquierda? Así sabe hacia qué lado tiene que girar." }
      ] },
      { k: 'quiz', ph: 'mans', q: 'Si plou, agafo el paraigua; <b>si no</b>, agafo la gorra. Avui fa sol. Què agafo?|Si llueve, cojo el paraguas; <b>si no</b>, cojo la gorra. Hoy hace sol. ¿Qué cojo?',
        opts: ['La gorra|La gorra', 'El paraigua|El paraguas', 'Totes dues coses|Las dos cosas'], a: 0,
        ex: "No plou, per tant es fa la branca del «si no»: la gorra. Mai es fan totes dues.|No llueve, por lo tanto se hace la rama del «si no»: la gorra. Nunca se hacen las dos." },
      { k: 'unplug', ph: 'mans', ico: '🔀', title: 'El meu diagrama de decisió|Mi diagrama de decisión', t: 'Amb un full, un llapis i algú de casa.|Con una hoja, un lápiz y alguien de casa.',
        steps: ["Penseu una decisió de cada dia: per exemple, «Fa fred?».|Pensad una decisión de cada día: por ejemplo, «¿Hace frío?».",
          "Dibuixeu un rombe amb la pregunta i dues fletxes: una diu <b>sí</b> i l'altra, <b>si no</b>.|Dibujad un rombo con la pregunta y dos flechas: una dice <b>sí</b> y la otra, <b>si no</b>.",
          "Al final de cada fletxa, dibuixeu què feu: «em poso la jaqueta» o «vaig en samarreta».|Al final de cada flecha, dibujad qué hacéis: «me pongo la chaqueta» o «voy en camiseta».",
          "Feu-ne un altre amb una pregunta dins d'una altra, com el d'en Bit al bosc.|Haced otro con una pregunta dentro de otra, como el de Bit en el bosque."] },
      { k: 'predict', ph: 'prova', q: "Programa: <b>Endavant; si hi ha camí a l'esquerra, gira a l'esquerra; si no, gira a la dreta; Endavant; Endavant</b>. On acabarà en Bit?|Programa: <b>Adelante; si hay camino a la izquierda, gira a la izquierda; si no, gira a la derecha; Adelante; Adelante</b>. ¿Dónde terminará Bit?",
        w: { map: ['..B..', 'AR##C', '..^..'] }, prog: TQ('f if:freeL{ l } else{ r } f f'), a: 'C',
        ex: "A l'esquerra hi ha una roca: la condició és falsa i en Bit fa la branca del «si no». Gira a la dreta i acaba a la C.|A la izquierda hay una roca: la condición es falsa y Bit hace la rama del «si no». Gira a la derecha y termina en la C." },
      { k: 'spot', ph: 'investiga', q: 'En aquest camí tots els revolts són cap a la dreta, però el programa falla. <b>Toca el bloc equivocat</b>.|En este camino todas las curvas son hacia la derecha, pero el programa falla. <b>Toca el bloque equivocado</b>.',
        w: { map: ['#####', '#...F', '#....', '^....'] }, prog: TPX('10{ if:free{ f } else{ l! } }'),
        ex: "Quan el camí no és lliure, en Bit gira a l'esquerra i surt de l'illa. A la branca del «si no» hi havia d'anar «Gira a la dreta».|Cuando el camino no está libre, Bit gira a la izquierda y se sale de la isla. En la rama del «si no» tenía que ir «Gira a la derecha»." },
      { k: 'move', ph: 'pausa', secs: 30, t: "<b>Si… si no… amb el cos!</b> Algú diu un animal. Si vola, fes les ales amb els braços; si no, camina com un elefant pel lloc. I ara: si neda, fes de peix; si no, salta com una granota!|<b>¡Si… si no… con el cuerpo!</b> Alguien dice un animal. Si vuela, haz las alas con los brazos; si no, camina como un elefante en el sitio. Y ahora: si nada, haz de pez; si no, ¡salta como una rana!" },
      { k: 'build', ph: 'repte', q: "Arribes a una cruïlla i a cada illa el camí gira cap a un costat diferent. Fes un programa que decideixi: <b>si hi ha camí a l'esquerra, gira a l'esquerra; si no, gira a la dreta</b>.|Llegas a un cruce y en cada isla el camino gira hacia un lado diferente. Haz un programa que decida: <b>si hay camino a la izquierda, gira a la izquierda; si no, gira a la derecha</b>.",
        w: { map: ['F##..', '..#..', '..#..', '..^..'], alts: [['..##F', '..#..', '..#..', '..^..']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['freeL', 'freeR', 'free', 'wall'], sol: TQ('3{ f } if:freeL{ l } else{ r } 2{ f }'),
        hint: "Primer, 3 passos fins a la cruïlla. Després, un «Si»: toca'l i tria «Afegeix si no». Al final, 2 passos més.|Primero, 3 pasos hasta el cruce. Después, un «Si»: tócalo y elige «Añade si no». Al final, 2 pasos más." },
      { k: 'build', ph: 'repte', q: 'A cada volta, en Bit fa una sola cosa: <b>si el camí és lliure, endavant; si no, gira a la dreta</b>. Fes un programa per a les 3 illes. Cal repetir-ho <b>10 vegades</b>.|En cada vuelta, Bit hace una sola cosa: <b>si el camino está libre, adelante; si no, gira a la derecha</b>. Haz un programa para las 3 islas. Hay que repetirlo <b>10 veces</b>.',
        w: { map: ['#####', '#...F', '#....', '^....'], alts: [['####R', '#..#.', '#..F.', '^....'], ['R....', '#####', '#...#', '^...F']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['free', 'wall', 'freeL', 'freeR'], sol: TQ('10{ if:free{ f } else{ r } }'),
        hint: 'Dins del «Repeteix», un sol «Si… si no…»: Endavant a la primera branca i Gira a la dreta a la segona.|Dentro del «Repite», un solo «Si… si no…»: Adelante en la primera rama y Gira a la derecha en la segunda.' },
      { k: 'build', ph: 'repte', q: "Ui! Algú ha posat les branques al revés i en Bit gira quan hauria d'avançar. <b>Arregla-ho</b> perquè funcioni a les 3 illes. Aquí els revolts són cap a l'esquerra d'en Bit.|¡Uy! Alguien ha puesto las ramas al revés y Bit gira cuando debería avanzar. <b>Arréglalo</b> para que funcione en las 3 islas. Aquí las curvas son hacia la izquierda de Bit.",
        w: { map: ['v....', '#....', '#...F', '#####'], alts: [['v....', '#..F.', '#..#.', '####R'], ['v...F', '#...#', '#####', '.....']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['free', 'wall'],
        prog: TQ('10{ if:free{ l } else{ f } }'), sol: TQ('10{ if:free{ f } else{ l } }'),
        hint: 'Si el camí és lliure, què ha de fer en Bit? I si no ho és?|Si el camino está libre, ¿qué tiene que hacer Bit? ¿Y si no lo está?' },
      { k: 'build', ph: 'repte', q: "Ara el camí gira a vegades a l'esquerra i a vegades a la dreta. Fes una <b>decisió dins d'una altra</b>: si el camí és lliure, endavant; si no, si hi ha camí a l'esquerra, gira a l'esquerra; si no, gira a la dreta. Cal repetir-ho 11 vegades.|Ahora el camino gira a veces a la izquierda y a veces a la derecha. Haz una <b>decisión dentro de otra</b>: si el camino está libre, adelante; si no, si hay camino a la izquierda, gira a la izquierda; si no, gira a la derecha. Hay que repetirlo 11 veces.",
        w: { map: ['..##F', '..#..', '###..', '#....', '^....'], alts: [['.....', '.F##.', '...#.', '####.', '^....']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['free', 'freeL', 'freeR', 'wall'], max: 6, sol: TQ('11{ if:free{ f } else{ if:freeL{ l } else{ r } } }'),
        hint: "Toca l'espai buit de dins del «si no» i posa-hi el segon «Si», també amb el seu «si no».|Toca el espacio vacío de dentro del «si no» y pon ahí el segundo «Si», también con su «si no»." },
      { k: 'create', ph: 'crea', name: 'La ruta del bosc|La ruta del bosque',
        q: "<b>Crea la teva ruta pel bosc!</b> Hi ha dues illes amb revolts cap als dos costats, i en totes dues cal repetir 11 vegades. Fes un programa que funcioni a les dues i que faci servir el bloc <b>Si… si no…</b>. Tria tu les condicions!|<b>¡Crea tu ruta por el bosque!</b> Hay dos islas con curvas hacia los dos lados, y en las dos hay que repetir 11 veces. Haz un programa que funcione en las dos y que use el bloque <b>Si… si no…</b>. ¡Elige tú las condiciones!",
        crit: ['Funciona a les 2 illes|Funciona en las 2 islas', 'Fa servir «Si… si no…»|Usa «Si… si no…»', "Pots explicar què fa cada branca|Puedes explicar qué hace cada rama"],
        check: p => JSON.stringify(p).includes('"e":[') ? null : 'Funciona, però fes servir almenys un «Si… si no…». Toca un «Si» i tria «Afegeix si no».|Funciona, pero usa al menos un «Si… si no…». Toca un «Si» y elige «Añade si no».',
        w: { map: ['>##...', '..#...', '..####', '.....F', '......'], alts: [['>#....', '.#....', '.####.', '....#.', '....F.']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['free', 'freeL', 'freeR', 'wall'], sol: TQ('11{ if:free{ f } else{ if:freeL{ l } else{ r } } }') },
      { k: 'quiz', ph: 'tanca', q: 'En un bloc «Si… si no…», quantes branques fa en Bit cada vegada?|En un bloque «Si… si no…», ¿cuántas ramas hace Bit cada vez?', opts: ['Una: la del «si» o la del «si no»|Una: la del «si» o la del «si no»', 'Les dues|Las dos', 'Cap|Ninguna'], a: 0 },
      { k: 'quiz', ph: 'tanca', w: { map: ['...', '.v.', '...'] }, q: "En Bit mira avall. Cap on és <b>la seva esquerra</b>, a la pantalla?|Bit mira abajo. ¿Hacia dónde está <b>su izquierda</b>, en la pantalla?", opts: ['→ Cap a la dreta de la pantalla|→ Hacia la derecha de la pantalla', "← Cap a l'esquerra de la pantalla|← Hacia la izquierda de la pantalla", '↑ Amunt|↑ Arriba'], a: 0,
        ex: "Posa't al seu lloc: quan en Bit et mira, la seva esquerra és la teva dreta.|Ponte en su lugar: cuando Bit te mira, su izquierda es tu derecha." },
      { k: 'feel', ph: 'tanca' }
    ] },
  { id: 'r4-4', t: 'Projecte: el laberint|Proyecto: el laberinto', min: 40, proj: true, badge: 'u4lab',
    learn: ['Una estratègia és una manera de pensar que serveix per a molts problemes semblants.|Una estrategia es una manera de pensar que sirve para muchos problemas parecidos.',
      "Seguint la paret de la dreta, en Bit surt de laberints diferents amb el mateix programa.|Siguiendo la pared de la derecha, Bit sale de laberintos diferentes con el mismo programa.",
      'Un programa està acabat quan funciona a totes les illes.|Un programa está terminado cuando funciona en todas las islas.'],
    steps: [
      { k: 'quiz', ph: 'recorda', q: 'En Bit té: <b>si el camí és lliure, Endavant; si no, Gira a la dreta</b>. Té una roca davant. Què fa?|Bit tiene: <b>si el camino está libre, Adelante; si no, Gira a la derecha</b>. Tiene una roca delante. ¿Qué hace?',
        opts: ['Gira a la dreta|Gira a la derecha', 'Endavant|Adelante', 'Les dues coses|Las dos cosas'], a: 0,
        ex: 'El camí no és lliure: fa la branca del «si no».|El camino no está libre: hace la rama del «si no».' },
      { k: 'story', ph: 'missio', who: 'both', scene: 'illa', title: 'La festa del laberint|La fiesta del laberinto',
        t: "És la festa major! Al costat del far han plantat <b>laberints de bardissa</b>, i cada illa en té un de diferent. Qui arribi a la bandera de tots, encendrà el gran fanal de la festa.|¡Es la fiesta mayor! Al lado del faro han plantado <b>laberintos de seto</b>, y cada isla tiene uno diferente. Quien llegue a la bandera de todos, encenderá el gran farol de la fiesta." },
      { k: 'story', ph: 'missio', who: 'bit', mood: 'think',
        t: "BIP… Si faig un programa per a cada laberint, no acabaré mai! Necessito una <b>estratègia</b>: una manera de decidir que funcioni a <b>tots</b> els laberints.|BIP… Si hago un programa para cada laberinto, ¡no terminaré nunca! Necesito una <b>estrategia</b>: una manera de decidir que funcione en <b>todos</b> los laberintos." },
      { k: 'learn', ph: 'descobreix', cards: [
        { k: 'Estratègia|Estrategia', t: 'Segueix la paret|Sigue la pared', anim: 'u4maze',
          x: "Hi ha un truc conegut per sortir de molts laberints: <b>posa la mà dreta a la paret i no la treguis mai</b>. Si camines sempre tocant-la, acabes passant per tots els passadissos i trobes la sortida. Una manera de resoldre problemes com aquest es diu <span class='hl'>estratègia</span>.|Hay un truco conocido para salir de muchos laberintos: <b>pon la mano derecha en la pared y no la quites nunca</b>. Si caminas siempre tocándola, acabas pasando por todos los pasillos y encuentras la salida. Una manera de resolver problemas como este se llama <span class='hl'>estrategia</span>.",
          tip: "Funciona als laberints on totes les parets estan unides, com els d'avui.|Funciona en los laberintos donde todas las paredes están unidas, como los de hoy." },
        { k: 'En blocs|En bloques', t: "La mà dreta d'en Bit|La mano derecha de Bit", demo: { w: { map: ['>.###', '#...#', '###.#', '..#.#', 'F####'] }, prog: TQ('9{ if:freeR{ r } if:free{ f } else{ l } }') },
          x: "En blocs, l'estratègia és així. A cada volta: <b>si hi ha camí a la dreta, gira a la dreta</b>. Després: <b>si el camí és lliure, endavant; si no, gira a l'esquerra</b>. Mira com en Bit no deixa mai la paret de la seva dreta.|En bloques, la estrategia es así. En cada vuelta: <b>si hay camino a la derecha, gira a la derecha</b>. Después: <b>si el camino está libre, adelante; si no, gira a la izquierda</b>. Mira cómo Bit no deja nunca la pared de su derecha." },
        { k: 'Pla|Plan', t: "Primer l'estratègia, després els blocs|Primero la estrategia, después los bloques", anim: 'plan',
          x: "Com al projecte del repartidor: primer pensa <b>l'estratègia</b> amb paraules, després passa-la a blocs i, al final, <b>prova-la</b>. Si falla, busca el bug pas a pas.|Como en el proyecto del repartidor: primero piensa <b>la estrategia</b> con palabras, después pásala a bloques y, al final, <b>pruébala</b>. Si falla, busca el bug paso a paso." },
        { k: 'Compte!|¡Cuidado!', t: 'Prova-ho a totes les illes|Pruébalo en todas las islas', anim: 'u4isles',
          x: "Un programa pot funcionar en una illa i fallar en una altra. Per això en Bit el prova a <b>totes les illes</b>, l'una darrere l'altra. Només quan surten totes bé, el programa està acabat.|Un programa puede funcionar en una isla y fallar en otra. Por eso Bit lo prueba en <b>todas las islas</b>, una detrás de otra. Solo cuando salen todas bien, el programa está terminado.",
          bad: 'Provar el programa en una sola illa i donar-lo per acabat.|Probar el programa en una sola isla y darlo por terminado.', good: 'Provar-lo a totes les illes i arreglar el que falli.|Probarlo en todas las islas y arreglar lo que falle.' }
      ] },
      { k: 'seq', ph: 'mans', q: "Ordena l'estratègia de la mà dreta, tal com la pensa en Bit a cada volta.|Ordena la estrategia de la mano derecha, tal como la piensa Bit en cada vuelta.",
        items: ['Miro si hi ha camí a la meva dreta.|Miro si hay camino a mi derecha.', "Si n'hi ha, giro a la dreta.|Si lo hay, giro a la derecha.", 'Miro si el camí del davant és lliure.|Miro si el camino de delante está libre.', "Si ho és, avanço; si no, giro a l'esquerra.|Si lo está, avanzo; si no, giro a la izquierda."],
        ex: "Aquesta és l'estratègia: primer la dreta, després el davant, i si no hi ha res, girar a l'esquerra.|Esta es la estrategia: primero la derecha, después delante, y si no hay nada, girar a la izquierda." },
      { k: 'unplug', ph: 'mans', ico: '🧱', title: 'El laberint de cadires|El laberinto de sillas', t: 'Amb algú de casa i unes quantes cadires, coixins o caixes.|Con alguien de casa y unas cuantas sillas, cojines o cajas.',
        steps: ["Feu un laberint petit a terra amb cadires i coixins. Amagueu un objecte a la sortida: és la bandera.|Haced un laberinto pequeño en el suelo con sillas y cojines. Esconded un objeto en la salida: es la bandera.",
          "El robot camina a poc a poc amb la <b>mà dreta tocant sempre la «paret»</b>.|El robot camina despacio con la <b>mano derecha tocando siempre la «pared»</b>.",
          "L'altra persona compta quants passos fa fins a la bandera.|La otra persona cuenta cuántos pasos da hasta la bandera.",
          "Canvieu el laberint i torneu-ho a provar amb la mateixa estratègia. Funciona?|Cambiad el laberinto y volved a probar con la misma estrategia. ¿Funciona?"] },
      { k: 'parsons', ph: 'prova', q: "Ordena els blocs perquè en Bit passi la cruïlla a les dues illes. Primer decideix i després avança.|Ordena los bloques para que Bit pase el cruce en las dos islas. Primero decide y después avanza.",
        w: { map: ['F##..', '..#..', '..^..'], alts: [['..##F', '..#..', '..^..']] }, pool: TQ('2{ f } if:freeR{ r } else{ l } 2{ f }'), sol: TQ('2{ f } if:freeR{ r } else{ l } 2{ f }'),
        hint: 'Primer arriba a la cruïlla, després decideix cap on gira i, al final, avança fins a la bandera.|Primero llega al cruce, después decide hacia dónde gira y, al final, avanza hasta la bandera.' },
      { k: 'predict', ph: 'prova', q: "Programa: <b>Repeteix 5 vegades: si hi ha camí a la dreta, gira a la dreta; si el camí és lliure, endavant; si no, gira a l'esquerra</b>. On acabarà en Bit?|Programa: <b>Repite 5 veces: si hay camino a la derecha, gira a la derecha; si el camino está libre, adelante; si no, gira a la izquierda</b>. ¿Dónde terminará Bit?",
        w: { map: ['>##B', '.#..', 'A##C'] }, prog: TQ('5{ if:freeR{ r } if:free{ f } else{ l } }'), a: 'A',
        ex: "A cada cruïlla, en Bit tria primer el camí de la seva dreta: baixa i després gira cap a la A.|En cada cruce, Bit elige primero el camino de su derecha: baja y después gira hacia la A." },
      { k: 'quiz', ph: 'prova', q: 'Al laberint, en Bit segueix la paret de la dreta. Arriba a un lloc on hi ha camí <b>a la dreta</b> i també <b>davant</b>. Què fa?|En el laberinto, Bit sigue la pared de la derecha. Llega a un sitio donde hay camino <b>a la derecha</b> y también <b>delante</b>. ¿Qué hace?',
        opts: ['Gira a la dreta|Gira a la derecha', 'Continua endavant|Sigue adelante', 'Fa mitja volta|Da media vuelta'], a: 0,
        ex: "L'estratègia diu que primer mira la dreta: si hi ha camí, gira cap allà.|La estrategia dice que primero mira la derecha: si hay camino, gira hacia allí." },
      { k: 'move', ph: 'pausa', secs: 30, t: "Estira els braços com si toquessis les parets d'un passadís estret. Fes 3 passos, gira a la dreta, fes-ne 2, gira a l'esquerra… i ara torna enrere fins al principi!|Estira los brazos como si tocaras las paredes de un pasillo estrecho. Da 3 pasos, gira a la derecha, da 2, gira a la izquierda… ¡y ahora vuelve atrás hasta el principio!" },
      { k: 'build', ph: 'repte', q: "<b>Laberint 1.</b> El programa ja té la primera part de l'estratègia: <b>si hi ha camí a la dreta, gira a la dreta</b>. Afegeix-hi la segona: <b>si el camí és lliure, endavant; si no, gira a l'esquerra</b>. Ha de funcionar als 2 laberints.|<b>Laberinto 1.</b> El programa ya tiene la primera parte de la estrategia: <b>si hay camino a la derecha, gira a la derecha</b>. Añádele la segunda: <b>si el camino está libre, adelante; si no, gira a la izquierda</b>. Tiene que funcionar en los 2 laberintos.",
        w: { map: ['>.###', '#...#', '###.#', '..#.#', 'F####'], alts: [['>##.#', '..#.#', '#.###', '#...#', '####F']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['freeR', 'free', 'freeL', 'wall'],
        prog: TQ('9{ if:freeR{ r } }'), sol: TQ('9{ if:freeR{ r } if:free{ f } else{ l } }'),
        hint: "El segon «Si» va dins del «Repeteix», just després del primer. Recorda afegir-li el «si no».|El segundo «Si» va dentro del «Repite», justo después del primero. Recuerda añadirle el «si no»." },
      { k: 'build', ph: 'repte', q: "<b>Laberint 2.</b> En Bit es queda encallat en un racó i no arriba a la bandera. A l'estratègia li falta un tros: <b>què fa quan té la paret davant?</b> Arregla-ho.|<b>Laberinto 2.</b> Bit se queda atascado en un rincón y no llega a la bandera. A la estrategia le falta un trozo: <b>¿qué hace cuando tiene la pared delante?</b> Arréglalo.",
        w: { map: ['>.###', '#...#', '#.##F', '#.#.#', '###.#'], alts: [['>####', '....#', '##F.#', '#.#.#', '#.###']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['freeR', 'free', 'freeL', 'wall'],
        prog: TQ('12{ if:freeR{ r } if:free{ f } }'), sol: TQ('12{ if:freeR{ r } if:free{ f } else{ l } }'),
        hint: "Executa'l pas a pas i mira què passa al racó. Quan el camí no és lliure, en Bit ha de girar: afegeix un «si no» al segon «Si».|Ejecútalo paso a paso y mira qué pasa en el rincón. Cuando el camino no está libre, Bit tiene que girar: añade un «si no» al segundo «Si»." },
      { k: 'story', ph: 'crea', who: 'numi', title: 'El projecte final|El proyecto final',
        t: 'Ara et toca a tu: <b>els 3 laberints de la festa</b>, amb un sol programa. Segueix el pla:|Ahora te toca a ti: <b>los 3 laberintos de la fiesta</b>, con un solo programa. Sigue el plan:',
        box: "<ol><li>Mira els 3 laberints (toca les pestanyes de les illes).</li><li>Tria l'<b>estratègia</b> i digues-la amb paraules.</li><li>Passa-la a blocs.</li><li>Executa: en Bit la prova a totes les illes.</li><li>Si falla, fes <b>Pas a pas</b> i arregla el bug.</li></ol>|<ol><li>Mira los 3 laberintos (toca las pestañas de las islas).</li><li>Elige la <b>estrategia</b> y dila con palabras.</li><li>Pásala a bloques.</li><li>Ejecuta: Bit la prueba en todas las islas.</li><li>Si falla, haz <b>Paso a paso</b> y arregla el bug.</li></ol>" },
      { k: 'create', ph: 'crea', name: 'El laberint de la festa|El laberinto de la fiesta',
        q: "<b>Projecte final de la unitat!</b> Fes arribar en Bit a la bandera dels <b>3 laberints de la festa</b> amb un sol programa. Fes servir l'estratègia que vulguis i prova-la a totes les illes. Pista: amb <b>Repeteix 10</b> n'hi ha prou.|<b>¡Proyecto final de la unidad!</b> Haz llegar a Bit a la bandera de los <b>3 laberintos de la fiesta</b> con un solo programa. Usa la estrategia que quieras y pruébala en todas las islas. Pista: con <b>Repite 10</b> es suficiente.",
        crit: ['Funciona als 3 laberints|Funciona en los 3 laberintos', 'Fa servir «Repeteix» i «Si… si no…»|Usa «Repite» y «Si… si no…»', "L'has provat i millorat|Lo has probado y mejorado"],
        check: p => p.some(b => b.k === 'rep') && JSON.stringify(p).includes('"e":[') ? null : 'Funciona, però el projecte demana un «Repeteix» i almenys un «Si… si no…».|Funciona, pero el proyecto pide un «Repite» y al menos un «Si… si no…».',
        w: { map: ['>.###', '#...#', '#.F##', '#.#.#', '###.#'], alts: [['>####', '....#', '###.#', '#.#.#', '#.F##'], ['>.##F', '#.#.#', '###.#', '....#', '#####']] }, pal: ['fwd', 'left', 'right', 'rep', 'if', 'else'], conds: ['freeR', 'free', 'freeL', 'wall'],
        sol: TQ('10{ if:freeR{ r } if:free{ f } else{ l } }') },
      { k: 'quiz', ph: 'tanca', q: 'Què és una <b>estratègia</b>?|¿Qué es una <b>estrategia</b>?', opts: ['Una manera de pensar per resoldre molts problemes semblants|Una manera de pensar para resolver muchos problemas parecidos', 'Un bloc nou|Un bloque nuevo', 'Un laberint|Un laberinto'], a: 0 },
      { k: 'quiz', ph: 'tanca', q: 'Per què provem el programa a totes les illes?|¿Por qué probamos el programa en todas las islas?', opts: ['Perquè pot funcionar en una i fallar en una altra|Porque puede funcionar en una y fallar en otra', 'Perquè queda més bonic|Porque queda más bonito', "No cal: amb una n'hi ha prou|No hace falta: con una es suficiente"], a: 0 },
      { k: 'feel', ph: 'tanca' }
    ] }
] };
